schema.sql:
CREATE ROLE app LOGIN NOSUPERUSER NOINHERIT;

CREATE TABLE accounts (
    id text PRIMARY KEY,
    is_demo boolean NOT NULL
);

CREATE TABLE orders (
    id text PRIMARY KEY,
    account_id text NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,
    state text NOT NULL DEFAULT 'NEW'
);

CREATE TABLE invoice_audit (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id text NOT NULL REFERENCES orders(id) ON DELETE RESTRICT
);

-- Only privileged functions owned by the table owner can remove audit rows.
-- In particular, session settings cannot enable this branch for app.
CREATE FUNCTION reject_audit_delete() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF current_user = (SELECT pg_get_userbyid(c.relowner)
                       FROM pg_class AS c
                       WHERE c.oid = TG_RELID) THEN
        RETURN OLD;
    END IF;
    RAISE EXCEPTION 'immutable' USING ERRCODE = '55000';
END
$$;

CREATE TRIGGER invoice_audit_immutable
BEFORE DELETE ON invoice_audit
FOR EACH ROW EXECUTE FUNCTION reject_audit_delete();

CREATE FUNCTION complete_order(order_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    current_state text;
BEGIN
    SELECT state INTO current_state
      FROM public.orders
     WHERE id = complete_order.order_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'order % does not exist', complete_order.order_id
            USING ERRCODE = 'P0002';
    END IF;
    IF current_state = 'DONE' THEN
        RETURN;
    END IF;

    UPDATE public.orders SET state = 'DONE'
     WHERE id = complete_order.order_id;
    INSERT INTO public.invoice_audit(order_id)
    VALUES (complete_order.order_id);
END
$$;

CREATE FUNCTION purge_demo_account(account_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
    rel record;
BEGIN
    -- Restrict reset to the relations this schema knows how to clean. Check
    -- before any DELETE so an added FK cannot cause a partial reset.
    FOR rel IN
        SELECT DISTINCT child.relname
          FROM pg_constraint AS fk
          JOIN pg_class AS child ON child.oid = fk.conrelid
          JOIN pg_namespace AS child_ns ON child_ns.oid = child.relnamespace
          JOIN pg_class AS parent ON parent.oid = fk.confrelid
          JOIN pg_namespace AS parent_ns ON parent_ns.oid = parent.relnamespace
         WHERE fk.contype = 'f'
           AND child_ns.nspname = 'public'
           AND parent_ns.nspname = 'public'
           AND parent.relname IN ('accounts', 'orders', 'invoice_audit')
           AND child.relname NOT IN ('orders', 'invoice_audit')
    LOOP
        RAISE EXCEPTION 'unsupported relation: %', rel.relname USING ERRCODE = 'P0001';
    END LOOP;

    IF NOT EXISTS (
        SELECT 1 FROM public.accounts
         WHERE id = purge_demo_account.account_id AND is_demo
    ) THEN
        RETURN;
    END IF;

    DELETE FROM public.invoice_audit AS a
     USING public.orders AS o
     WHERE a.order_id = o.id
       AND o.account_id = purge_demo_account.account_id;
    DELETE FROM public.orders
     WHERE orders.account_id = purge_demo_account.account_id;
    DELETE FROM public.accounts
     WHERE accounts.id = purge_demo_account.account_id
       AND accounts.is_demo;
END
$$;

REVOKE ALL ON FUNCTION reject_audit_delete() FROM PUBLIC;
REVOKE ALL ON FUNCTION complete_order(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION purge_demo_account(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION complete_order(text) TO app;
GRANT EXECUTE ON FUNCTION purge_demo_account(text) TO app;

REVOKE ALL ON ALL TABLES IN SCHEMA public FROM app;
GRANT SELECT ON accounts, orders, invoice_audit TO app;
GRANT USAGE, SELECT ON SEQUENCE invoice_audit_id_seq TO app;
